package com.imgvault.app.core.crypto

import java.util.Base64
import javax.crypto.SecretKey
import javax.crypto.spec.SecretKeySpec
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The Kotlin vault crypto is pinned against GOLDEN VECTORS generated by the
 * real JS implementation (`packages/shared/vaultCrypto.js`) — the same file
 * the extension and the web app use. If the two ever drift, the JS side stays
 * the source of truth and this test fails.
 *
 * The vectors were produced by running the JS module with a fixed passcode, a
 * fixed PBKDF2 salt and a fixed master key (2026-11-26).
 */
class VaultCryptoTest {

    private val passcode = "correct horse battery staple"
    private val salt = "000102030405060708090a0b0c0d0e0f"
    private val kdfSalt = "101112131415161718191a1b1c1d1e1f"

    // --- vectors from packages/shared/vaultCrypto.js ---
    private val passHash =
        "2b2da9c773503e4dffcc2fe5d581100dbdeb2164d8cec01a1ba428ee800bc6d1"
    private val wrappedMasterKey =
        "qrvM3e7/ABEiM0RVhnr21EcmfDJXc/hlitVr62D3Gfvp/hkBtbHp369SojNPj7/nZ2mQbRs6RRqnp9v3"
    private val masterKeyHex =
        "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"
    private val encryptedMetadataB64 =
        "tOBDgWp01C4YzBCbHjBEzncHy9fXOEUt22EAXozFSOKne893v6mESiZOiSl2BMO4JeaqZ8zxcKCjC2kZXq4UaUVculwdcwv3mUytHxezdHO1yS1vqpWUBroWBf/58yo="
    private val metadataPlain =
        """{"fileName":"holiday.jpg","mimeType":"image/jpeg","tags":["a","b"]}"""
    private val encryptedBlobB64 =
        "SVZHMUMAAAAAAAAAAACAAJnD966ZlvfMnEQRk2Slw53OrdwQpyrB0TMuNO8CKlvK76WGkom2cEbhnydYj37LG/uxxAlI5YOkKQhjgzPfMlwvqhMKtgLkV6PIYcieVAEg0S+PdQGVMziQnR0adFXi"
    private val blobPlain = "hello vault, this is the plaintext that must survive the round trip"

    @Test
    fun `the passcode hash matches the JS implementation`() {
        assertEquals(passHash, VaultCrypto.hashVaultPasscode(passcode, salt))
    }

    @Test
    fun `the JS wrapped master key unwraps to the same master key`() {
        val config = VaultConfig(
            salt = salt,
            passHash = passHash,
            kdfSalt = kdfSalt,
            kdfIterations = VaultCrypto.KDF_ITERATIONS,
            wrappedMasterKey = wrappedMasterKey,
        )
        val key: SecretKey = VaultCrypto.unwrapMasterKey(config, passcode)
        assertEquals(masterKeyHex, key.encoded.toHex())
    }

    @Test
    fun `the JS encrypted metadata decrypts to the same JSON`() {
        val key = SecretKeySpec(masterKeyHex.hexToBytes(), "AES")
        assertEquals(metadataPlain, VaultCrypto.decryptMetadata(key, encryptedMetadataB64))
    }

    @Test
    fun `the JS encrypted blob decrypts to the same bytes`() {
        val key = SecretKeySpec(masterKeyHex.hexToBytes(), "AES")
        val blob = Base64.getDecoder().decode(encryptedBlobB64)

        val header = VaultCrypto.parseVaultBlobHeader(blob)
        assertNotNull(header)
        assertEquals(67L, header!!.total)
        assertEquals(8388608, header.chunkSize)

        val layout = VaultCrypto.getVaultChunkLayout(header.total, header.chunkSize)
        assertEquals(1, layout.chunkCount)
        assertEquals(111L, layout.encryptedSize)

        assertEquals(blobPlain, String(VaultCrypto.decryptBlob(key, blob), Charsets.UTF_8))
    }

    @Test
    fun `a blob that is not IVG1 is still readable (legacy single-shot format)`() {
        val key = SecretKeySpec(masterKeyHex.hexToBytes(), "AES")
        val plain = "legacy payload".toByteArray(Charsets.UTF_8)
        val legacy = VaultCrypto.encryptRaw(key, plain)
        assertNull(VaultCrypto.parseVaultBlobHeader(legacy))
        assertArrayEquals(plain, VaultCrypto.decryptBlob(key, legacy))
    }

    @Test
    fun `the Kotlin round trip keeps the bytes`() {
        val key = SecretKeySpec(masterKeyHex.hexToBytes(), "AES")
        val plain = ByteArray(200_000) { (it % 251).toByte() }

        val encrypted = VaultCrypto.encryptBlob(key, plain)
        val header = VaultCrypto.parseVaultBlobHeader(encrypted)
        assertNotNull(header)
        assertEquals(plain.size.toLong(), header!!.total)
        assertArrayEquals(plain, VaultCrypto.decryptBlob(key, encrypted))

        val meta = """{"fileName":"a.bin","mimeType":"application/octet-stream"}"""
        assertEquals(meta, VaultCrypto.decryptMetadata(key, VaultCrypto.encryptMetadata(key, meta)))
    }

    @Test
    fun `a wrong passcode fails loudly instead of returning garbage`() {
        val config = VaultCrypto.createVaultConfig(passcode)
        var failed = false
        try {
            VaultCrypto.unwrapMasterKey(config, "not the passcode")
        } catch (error: Exception) {
            failed = true
            assertTrue(error.message?.isNotBlank() == true)
        }
        assertTrue("a wrong passcode must throw", failed)
    }

    @Test
    fun `a new config wraps and unwraps its own master key`() {
        val config = VaultCrypto.createVaultConfig(passcode)
        assertEquals(VaultCrypto.KDF_ITERATIONS, config.kdfIterations)
        assertEquals(VaultCrypto.VAULT_VERSION, config.vaultVersion)
        assertEquals(16, config.kdfSalt.length / 2)
        val key = VaultCrypto.unwrapMasterKey(config, passcode)
        assertEquals(32, key.encoded.size)
    }
}
